#include "ModTools.h"
#include "PlatformServices.h"
#include "EnginePaths.h"
#include "imgui.h"
#include <filesystem>
#include <cstring>
#ifndef _WIN32
#include <spawn.h>
extern char** environ;
#endif
namespace fs=std::filesystem;
namespace {
bool Launch(const Project& p,bool noMods,std::string& error){auto runtime=fs::u8path(p.RootDir())/RuntimeExecutableName();if(!fs::is_regular_file(runtime))runtime=fs::u8path(EngineExecutableDir())/RuntimeExecutableName();
#ifdef _WIN32
 std::vector<std::string> args{p.ProjectFile()};if(noMods)args.push_back("--no-mods");return WindowsLaunchProcess(runtime,args,error);
#else
 auto exe=runtime.u8string(),file=p.ProjectFile();std::vector<char*> args{exe.data(),file.data()};std::string no="--no-mods";if(noMods)args.push_back(no.data());args.push_back(nullptr);pid_t child=0;auto status=posix_spawn(&child,exe.c_str(),nullptr,nullptr,args.data(),environ);if(status){error="cannot launch game: "+std::string(std::strerror(status));return false;}return true;
#endif
}
}
void ModTools::Panel(EditorPanelState& state,EditorRequests& requests){if(!state.showMods)return;ImGui::SetNextWindowSize({650,650},ImGuiCond_FirstUseEver);if(!ImGui::Begin("Local mods / game kits",&state.showMods)){ImGui::End();return;}
 ImGui::TextWrapped("Optional local content. Trusted scripts have ordinary JudasJS world capabilities. Changes apply only to a fresh session / next launch.");
 if(state.project&&projectKey!=state.project->ProjectFile()){projectKey=state.project->ProjectFile();loaded=false;error.clear();std::snprintf(game,sizeof(game),"%s",projectKey.c_str());if(fs::exists(fs::u8path(state.project->RootDir())/"mod-authoring.json")){loaded=draft.Load("modmanifest",state.project->Resolve("mod.json"),error);if(loaded)std::snprintf(manifestText.data(),manifestText.size(),"%s",draft.Source().c_str());}}
 if(ImGui::CollapsingHeader("Game developer: export curated kit")){ImGui::InputText("New kit destination",destination,sizeof(destination));ImGui::InputText("Matching offline docs folder",docs,sizeof(docs));if(ImGui::Button("Export current game's kit")&&state.project){if(JudasMods::ExportKit(*state.project,destination,docs,error))state.status="Curated kit exported; original game unchanged";}}
 if(ImGui::CollapsingHeader("Mod author: new project",ImGuiTreeNodeFlags_DefaultOpen)){ImGui::InputText("Curated kit folder",kit,sizeof(kit));ImGui::InputText("New mod project folder",destination,sizeof(destination));ImGui::InputText("Stable mod ID",modId,sizeof(modId));if(ImGui::Button("Create kit-bound mod project")){Project p;if(JudasMods::NewModProject(kit,destination,modId,p,error)){state.status="Created "+p.ProjectFile()+"; use File / Open project";std::snprintf(game,sizeof(game),"%s",p.ProjectFile().c_str());}}}
 if(loaded&&state.project&&ImGui::CollapsingHeader("Current mod: draft and publication",ImGuiTreeNodeFlags_DefaultOpen)){JudasMods::KitBinding binding;if(JudasMods::ReadKitBinding(*state.project,binding,error)){ImGui::TextWrapped("Kit %s | mod %s. Kit references are read-only; Assets/ and Imports/ belong to this mod.",binding.identity.c_str(),binding.mod.c_str());ImGui::TextWrapped("Terrain: View / Terrain sculpt / paint. Create or open a Kit source and Fork to Imports/. Save, Cook, place in a scene, then bake navigation normally.");}
  ImGui::InputTextMultiline("Manifest draft",manifestText.data(),manifestText.size(),{0,210});if(ImGui::Button("Validate / apply draft"))draft.Replace(manifestText.data(),error);ImGui::SameLine();if(ImGui::Button("Undo draft")&&draft.Undo())std::snprintf(manifestText.data(),manifestText.size(),"%s",draft.Source().c_str());ImGui::SameLine();if(ImGui::Button("Redo draft")&&draft.Redo())std::snprintf(manifestText.data(),manifestText.size(),"%s",draft.Source().c_str());
  if(ImGui::Button("Save manifest")){if(draft.Replace(manifestText.data(),error)&&draft.Save(error))state.status="Saved manifest; package not published";}ImGui::SameLine();if(ImGui::Button("Cancel / reopen draft")){if(draft.Load("modmanifest",draft.Path(),error))std::snprintf(manifestText.data(),manifestText.size(),"%s",draft.Source().c_str());}if(draft.ExternalChanged())ImGui::TextColored({1,.4f,.2f,1},"External change: save refuses to overwrite it.");
  ImGui::InputText("Package output .judasmod",output,sizeof(output));if(ImGui::Button("Validate saved content / publish package")){if(draft.Dirty())error="Save the manifest before publication";else{JudasMods::Manifest m;JudasMods::Package p;if(JudasMods::ParseManifest(draft.Source(),m,error,true)&&JudasMods::AuthorPackage(*state.project,m,p,error)&&JudasMods::WritePackage(output,p,error))state.status="Published exact content: "+p.hash;}}ImGui::SameLine();if(ImGui::Button("Preview ordinary project"))requests.runProject=true;
 }
 if(ImGui::CollapsingHeader("Player: install / select / launch",ImGuiTreeNodeFlags_DefaultOpen)){ImGui::InputText("Installed game .judasproj",game,sizeof(game));ImGui::InputText("Local .judasmod file",packagePath,sizeof(packagePath));Project p;std::string detail;JudasMods::Contract contract;std::string root;const bool ready=p.Load(game,detail)&&JudasMods::ParseContract(p.Settings().modContract,contract,detail)&&JudasMods::GameModDirectory(contract,root,detail);if(!ready)ImGui::TextWrapped("%s",detail.c_str());ImGui::BeginDisabled(!ready);if(ImGui::Button("Inspect metadata (never executes)")){JudasMods::Package package;if(JudasMods::ReadPackage(packagePath,package,error))state.status=package.manifest.name+" | "+package.manifest.version+" | executable="+(package.manifest.executable?"yes":"no")+" | "+package.hash;}ImGui::SameLine();if(ImGui::Button("Install verified package")){JudasMods::Package package;if(JudasMods::ReadPackage(packagePath,package,error)){JudasMods::Store store(root);if(JudasMods::InstallForGame(p,package,error))state.status="Installed, not automatically enabled";}}
  ImGui::Checkbox("I trust this exact executable payload (required to enable scripts)",&trust);if(ready){JudasMods::Store store(root);std::vector<JudasMods::Installed> installed;std::vector<JudasMods::Loadout> selected;if(store.List(installed,selected,error))for(auto& version:installed){ImGui::PushID(version.file.c_str());const bool enabled=std::any_of(selected.begin(),selected.end(),[&](auto& s){return s.hash==version.hash&&s.id==version.id;});ImGui::TextWrapped("%s %s | %s | %s",version.id.c_str(),version.version.c_str(),enabled?"ENABLED":"installed",version.hash.c_str());if(ImGui::Button("Enable next launch")){if(store.Enable(contract,version.id,version.version,version.hash,trust,error))state.status="Selection saved; restart required";}ImGui::SameLine();if(ImGui::Button("Disable next launch"))store.Disable(version.id,error);ImGui::SameLine();if(ImGui::Button("Remove unused version"))store.Remove(version.id,version.version,version.hash,error);ImGui::PopID();}}
  if(ImGui::Button("Launch selected loadout")){Launch(p,false,error);}ImGui::SameLine();if(ImGui::Button("Launch without mods")){Launch(p,true,error);}ImGui::EndDisabled();}
 if(!error.empty()){ImGui::TextColored({1,.4f,.2f,1},"%s",error.c_str());}ImGui::End();}
